import json
import numpy as np
from PIL import Image
from rcb_client import Robot

r=Robot()
s=r.spec()
ranges=np.array(s['qpos']['range'])
def action(q):
    return np.clip(2*(np.array(q)-ranges[:,0])/(ranges[:,1]-ranges[:,0])-1,-1,1).tolist()
def save(o,label):
    for n,a in o.get('images',{}).items(): Image.fromarray(a).save(f'/app/output/{label}_{n}.png')
    print(label, {k:v for k,v in o.items() if k not in ('images','depth')},flush=True)
def pose(h,k,a):
    q=np.zeros(19); q[[2,7]]=h; q[[3,8]]=k; q[[4,9]]=a
    return q
if __name__=='__main__':
    o=r.observe(False); start=np.array(o['proprio']['joint_pos']); target=pose(-1.5,1.75,-.25)
    for t in range(1,61):
        q=start+(target-start)*min(t/60,1)
        o=r.step('qpos',action(q), images=(['room_camera'] if t%10==0 else False))
        if t%10==0: save(o,f't{t}')
        if o['done']: break
    if not o['done']:
        o=r.step('qpos',[action(target)]*100,images=['room_camera']); save(o,'hold')
